description:
The numbers behind `CreateFileMappingW` and `MapViewOfFile` (lessons 3.01 and 3.04):

```cpp
struct ViewPlan { std::uint64_t viewOffset; std::uint64_t delta; std::uint64_t viewLength; };

std::uint64_t pagesFor(std::uint64_t bytes);
std::pair<std::uint32_t, std::uint32_t> splitSize(std::uint64_t size);
ViewPlan planView(std::uint64_t fileOffset, std::uint64_t length);
bool validObjectName(const std::string& name);
```

- **pagesFor**: how many 4096-byte pages hold `bytes` (0 bytes need 0 pages).
- **splitSize** gives the high and low 32-bit halves a mapping size is passed as.
- **planView**: to read `length` bytes at `fileOffset`, the view must start at a multiple of 65 536: `viewOffset` is the offset rounded down, `delta` how far into the view the data starts, `viewLength` is `delta + length`.
- **validObjectName**: a name for a mapping, event or mutex is either a plain name, or `Local\` or `Global\` followed by a name; the name part must not be empty and must not contain `\`. The whole string is at most 260 characters.

starter.solution.cpp:
#include <cstdint>
#include <string>
#include <utility>

struct ViewPlan { std::uint64_t viewOffset; std::uint64_t delta; std::uint64_t viewLength; };

std::uint64_t pagesFor(std::uint64_t bytes) { return 0; }
std::pair<std::uint32_t, std::uint32_t> splitSize(std::uint64_t size) { return { 0, 0 }; }
ViewPlan planView(std::uint64_t fileOffset, std::uint64_t length) { return { 0, 0, 0 }; }
bool validObjectName(const std::string& name) { return false; }

solution.solution.cpp:
#include <cstdint>
#include <string>
#include <utility>

struct ViewPlan { std::uint64_t viewOffset; std::uint64_t delta; std::uint64_t viewLength; };

std::uint64_t pagesFor(std::uint64_t bytes) { return (bytes + 4095) / 4096; }

std::pair<std::uint32_t, std::uint32_t> splitSize(std::uint64_t size)
{
    return { static_cast<std::uint32_t>(size >> 32), static_cast<std::uint32_t>(size & 0xFFFFFFFFu) };
}

ViewPlan planView(std::uint64_t fileOffset, std::uint64_t length)
{
    const std::uint64_t start{ fileOffset / 65536 * 65536 };
    return { start, fileOffset - start, fileOffset - start + length };
}

bool validObjectName(const std::string& name)
{
    if (name.size() > 260) return false;
    std::string rest{ name };
    if (name.rfind("Local\\", 0) == 0) rest = name.substr(6);
    else if (name.rfind("Global\\", 0) == 0) rest = name.substr(7);
    return !rest.empty() && rest.find('\\') == std::string::npos;
}

unitTests:
TEST("pages") {
    CHECK_EQ(pagesFor(0), 0ull);
    CHECK_EQ(pagesFor(1), 1ull);
    CHECK_EQ(pagesFor(4096), 1ull);
    CHECK_EQ(pagesFor(4097), 2ull);
    CHECK_EQ(pagesFor(65536), 16ull);
}
TEST("sizes in two halves") {
    CHECK(splitSize(65536) == std::make_pair(0u, 65536u));
    CHECK(splitSize(0x1'0000'0000ull) == std::make_pair(1u, 0u));
    CHECK(splitSize(0x2'8000'0001ull) == std::make_pair(2u, 0x80000001u));
}
TEST("planning views") {
    const ViewPlan a{ planView(100000, 500) };
    CHECK_EQ(a.viewOffset, 65536ull); CHECK_EQ(a.delta, 34464ull); CHECK_EQ(a.viewLength, 34964ull);
    const ViewPlan b{ planView(200000, 10) };
    CHECK_EQ(b.viewOffset, 196608ull); CHECK_EQ(b.delta, 3392ull);
    const ViewPlan c{ planView(131072, 4096) };
    CHECK_EQ(c.viewOffset, 131072ull); CHECK_EQ(c.delta, 0ull); CHECK_EQ(c.viewLength, 4096ull);
}
TEST("object names") {
    CHECK(validObjectName("xenon-telemetry"));
    CHECK(validObjectName("Local\\xenon-telemetry"));
    CHECK(validObjectName("Global\\xenon-service"));
    CHECK(!validObjectName("Local\\"));
    CHECK(!validObjectName("Local\\a\\b"));
    CHECK(!validObjectName("Session\\1\\x"));
    CHECK(!validObjectName(""));
    CHECK(!validObjectName(std::string(261, 'x')));
}

